atoms.reference_cedar:
permit (principal is User, action == Action::"submitStep1", resource is Submission)
when {
    principal.role == "author"
    && resource.authors.contains(principal)
    && resource.step1Open
};

permit (principal is User, action == Action::"submitFullPaper", resource is Submission)
when {
    principal.role == "author"
    && resource.authors.contains(principal)
    && resource.step2Open
    && context.hasStep2Credential
};

permit (principal is User, action == Action::"updateStep1Info", resource is Submission)
when {
    principal.role == "author"
    && resource.authors.contains(principal)
    && resource.step2Open
    && context.hasStep2Credential
};

permit (principal is User, action == Action::"submitCameraReady", resource is Submission)
when {
    principal.role == "author"
    && resource.authors.contains(principal)
    && resource.selected
    && resource.reviewProcessDone
};

permit (principal is User, action == Action::"downloadPaper", resource is Submission)
when {
    principal.role == "reviewer"
    && resource.distributionDone
    && resource.assignedReviewers.contains(principal)
    && !resource.conflictedReviewers.contains(principal)
};

permit (principal is User, action == Action::"displayAbstract", resource is Submission)
when {
    principal.role == "reviewer"
    && resource.distributionDone
    && resource.assignedReviewers.contains(principal)
    && !resource.conflictedReviewers.contains(principal)
};

permit (principal is User, action == Action::"submitReview", resource is Submission)
when {
    principal.role == "reviewer"
    && resource.reviewOpen
    && resource.assignedReviewers.contains(principal)
    && !resource.conflictedReviewers.contains(principal)
};

permit (principal is User, action == Action::"updateReview", resource is Submission)
when {
    principal.role == "reviewer"
    && resource.reviewOpen
    && resource.assignedReviewers.contains(principal)
    && !resource.conflictedReviewers.contains(principal)
};

permit (principal is User, action == Action::"readOtherReviews", resource is Submission)
when {
    principal.role == "reviewer"
    && resource.assignedReviewers.contains(principal)
    && resource.reviewersSubmitted.contains(principal)
    && !resource.conflictedReviewers.contains(principal)
};

permit (principal is User, action == Action::"volunteerForConflictingPaper", resource is Submission)
when {
    principal.role == "reviewer"
    && principal.submittedAllAssignedReviews
    && resource.hasConflictingReviews
    && !resource.conflictedReviewers.contains(principal)
};

permit (principal is User, action == Action::"monitorReviewProcess", resource is ReviewOverview)
when {
    principal.role == "chair" || principal.role == "pcc"
};

permit (principal is User, action == Action::"askAdditionalReviewer", resource is ReviewOverview)
when {
    principal.role == "pcc"
    && resource.paper.onlyNonExpertReviews
};

permit (principal is User, action == Action::"accessReviewerDirectory", resource is ReviewerDirectory)
when {
    principal.role == "reviewer"
    && (principal == resource.owner || resource.allowedUsers.contains(principal))
};

permit (principal is User, action == Action::"readReviewFile", resource is ReviewFile)
when {
    principal.role == "reviewer"
    && resource.allowedUsers.contains(principal)
    && (principal == resource.directory.owner || resource.directory.allowedUsers.contains(principal))
};

permit (principal is User, action == Action::"submitStep1", resource is Submission)
when {
    principal.role == "author"
    && resource.authors.contains(principal)
    && resource.step1Open
};

permit (principal is User, action == Action::"readOtherReviews", resource is Submission)
when {
    principal.role == "reviewer"
    && resource.assignedReviewers.contains(principal)
    && resource.reviewersSubmitted.contains(principal)
    && !resource.conflictedReviewers.contains(principal)
};

permit (principal is User, action == Action::"askAdditionalReviewer", resource is ReviewOverview)
when {
    principal.role == "pcc"
    && resource.paper.onlyNonExpertReviews
};
